// Verify the KVL HMAC signature and timestamp window before doing anything else.
const crypto = require('crypto');
const secret = $env.KVL_N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('KVL_N8N_WEBHOOK_SECRET is not set in the n8n environment');
const h = $input.first().json.headers || {};
const ts = String(h['x-kvl-timestamp'] || '');
const sig = String(h['x-kvl-signature'] || '');
const raw = $input.first().json.rawBody ? $input.first().json.rawBody.toString() : JSON.stringify($input.first().json.body);
if (!ts || Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('stale or missing timestamp');
const expected = crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const a = Buffer.from(expected), b = Buffer.from(sig);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('invalid KVL signature');
const body = $input.first().json.body;
return [{ json: { event: body, correlation_id: h['x-kvl-correlation-id'], event_id: h['x-kvl-event-id'] } }];

// Build a signed request for the KVL API (HMAC-SHA256 over "<timestamp>.<body>").
const crypto = require('crypto');
const secret = $env.KVL_N8N_WEBHOOK_SECRET;
const ctx = $('Verify KVL signature').first().json;
const payload = {event_type: 'notification.send', correlation_id: ctx.correlation_id, data: {tenant_id: ctx.event.tenant_id, template: 'invoice_reminder', subject: 'Your invoice is due soon', message: 'You have an invoice that is due soon. Sign in to Billing to pay it.'}};
const body = JSON.stringify(payload);
const ts = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
return [{ json: { body, ts, signature, key: 'act:' + ctx.event_id } }];

